country_event = {
	id = ancrel.14
	hide_window = yes

	is_triggered_only = yes

	immediate = {
		set_global_flag = Zrocursor_system_discovered
		set_country_flag = last_zroni_system
		precursor_capital_spawn_system_effect = { PRECURSOR_FLAG = precursor_zroni_1 }
		if = {
			limit = { exists = event_target:precursor_spawn_system }
			event_target:precursor_spawn_system = {
				spawn_system = {
					min_distance = 10
					max_distance = 30
					max_jumps = 0
					initializer = "Zrocursor_system"
				}
				hidden_effect = {
					if = {
						limit = { last_created_system = { NOT = { has_hyperlane_to = prev } } }
						add_hyperlane = {
							from = this
							to = last_created_system
						}
					}
					else = {
						add_extra_hyperlane_to_spawned_system_effect = yes
					}
				}
			}
		}
		else = {
			# No usable system found (e.g. nomad arkship is mid-FTL with no waystations). Retry later.
			country_event = { id = ancrel.14 days = 30 }
		}
	}
}

